# -*- coding: utf-8 -*-
"""MANAPRINT — SOCIÉTÉ 7 boules (maquette CANVA de Maeva, 25/11/2026, « societe_canva_12_A4 »).
Reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE (3 colonnes x 4 rangées),
traits de coupe en pointillés. Chaque billet : cadre arrondi, titre SOCIÉTÉ, pastille
« Carte N° », « 2KEA & Associé – Papeete », la carte des îles (Bora Bora, Moorea, Tahaa,
Huahine, Raiatea, Tahiti) et 7 CASES : 3 à gauche, 3 à droite, 1 en bas au centre.
Le dessin du billet est rejoué TRAIT POUR TRAIT depuis la maquette (_DESSIN) et
enregistré une seule fois par document (fichier léger, impression d'une traite).
RÈGLE (inchangée) — 7 numéros différents de 1 à 75, du plus petit au plus grand
(la gauche de haut en bas, puis la case du bas, puis la droite de haut en bas).
Chiffres comme la maquette : écriture à empattements grasse (Times-Bold), 30 pt (le maximum).
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp).
(L'ancien societe.py — 8 cartons portrait — reste dans le dossier, il n'est plus appelé.)"""
import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import landscape, A4
from reportlab.lib import colors

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Times-Bold", 30      # comme la maquette (Liberation Serif Bold 30 pt)
ETROIT = 82                               # écriture « Narrow » de la maquette

# centres des 7 cases (dans l'ordre de lecture) et ligne de base des chiffres
CASES = [(32.88189, 79.10787), (32.88189, 45.65906), (32.88189, 12.21024),
         (140.315, 8.808661),
         (247.748, 79.10787), (247.748, 45.65906), (247.748, 12.21024)]
ILES = [("Bora Bora", 113.6595, 107.4494, 8.173821), ("Moorea", 87.24672, 92.37858, 8.332247),
        ("Tahaa", 114.4512, 80.35398, 7.859388), ("Raiatea", 111.2877, 63.84021, 8.884755),
        ("Tahiti", 146.6011, 56.30479, 8.147086), ("Huahine", 164.1876, 86.28612, 8.512433)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    """7 numéros DIFFÉRENTS de 1 à 75, du plus petit au plus grand ; jamais 2 billets pareils."""
    for _ in range(400):
        t = tuple(sorted(rng.sample(range(1, 76), 7)))
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, esp=0, etroit=100, contour=0):
    # objet texte : la position est EXACTEMENT celle de la maquette
    t = c.beginText(x, y); t.setFont(police, taille)
    if esp:
        t.setCharSpace(esp)
    if etroit != 100:
        t.setHorizScale(etroit)
    if contour:
        t.setTextRenderMode(2)
    t.setFillColor(col); t.textOut(s)
    if esp:
        t.setCharSpace(0)
    if etroit != 100:
        t.setHorizScale(100)
    if contour:
        t.setTextRenderMode(0)
    c.drawText(t)


def _billet(c, ox, oy, serie, nums, col):
    if not getattr(c, "_soc_modele", False):      # le dessin : une seule fois par document
        c.beginForm("SOCIETE_DESSIN", 0, 0, CELL_W, CELL_H)
        c._code.append("q\n" + _DESSIN + "\nQ")
        c.endForm()
        c._soc_modele = True
    c.saveState()
    c.translate(ox, oy)
    c.doForm("SOCIETE_DESSIN")
    _txt(c, "Carte N\u00b0 %05d" % serie, 209.7775, 130.1102, "Helvetica-Bold", 9, NOIR, etroit=ETROIT)
    _txt(c, "SOCI\u00c9T\u00c9", 16.44466, 125.0079, "Helvetica-Bold", 19, NOIR, esp=0.6, etroit=ETROIT)
    _txt(c, "2KEA & Associ\u00e9 \u2013 Papeete", 9.676892, 110.8346, "Helvetica-Bold", 7, NOIR, etroit=ETROIT)
    c.setLineWidth(0.45); c.setStrokeColor(NOIR)
    for nom, x, y, t in ILES:
        _txt(c, nom, x, y, "Helvetica-BoldOblique", t, NOIR, etroit=ETROIT, contour=1)
    for (cx, y), v in zip(CASES, nums):
        s = str(v); w = c.stringWidth(s, POLICE_NUM, T_NUM)
        _txt(c, s, cx - w / 2.0, y, POLICE_NUM, T_NUM, col)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    rng = random.Random(int(serie_start) * 100003 + 940000)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        entete = "  \u00b7  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 6)
        c.drawRightString(PAGE_W - DECAL_X, DECAL_Y / 2.0 - 2, "page %d" % no_page)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in (1, 2):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in (1, 2, 3):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


